struct Node;

/// Convert a count of days since the Unix epoch (1970-01-01) into a civil
/// (year, month, day) triple. This is Howard Hinnant's `civil_from_days`,
/// valid across the whole range we care about and dependency-free.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Format Unix `seconds` as an exactly-10-character `YYYY-MM-DD` string.
fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    // Clamp the year to a 4-digit field so `date` is always length 10.
    let y = y.rem_euclid(10_000);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch over the granted http-client capability. The result
        // is advisory only: a transport failure is returned as a value and we
        // ignore it, and nothing from the fetch feeds the output. The output is
        // derived solely from the clock, so the node's contract is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            tick.reason
        );
        let _enrichment = crate::aap::caps::http_client::fetch(&url);

        // The one authority that shapes the output: read the wall clock.
        let now = crate::wasi::clocks::wall_clock::now();
        let started = now.seconds; // u64, so `started >= 0` holds trivially.
        let date = format_date(started); // length == 10 by construction.

        RunInfo { date, started }
    }
}

export!(Node);
